{
  "name": "query_erpnext_data",
  "description": "Query ERPNext/Frappe records from any available DocType. Use this tool whenever the user asks to find, search, list, show, retrieve, count, total, sum, filter, sort, compare, or summarize ERPNext data. The database is the source of truth.",
  "parameters": {
    "type": "object",
    "properties": {
      "operation": {
        "type": "string",
        "enum": [
          "list",
          "count",
          "sum"
        ],
        "description": "list retrieves matching records, count returns the exact number of all matching records, and sum returns the exact total of a numeric field. When user asks for count, how many, or number of records (e.g. 'give me top item count', 'item count'), use ONLY count. Never call list and count together."
      },
      "doctype": {
        "type": "string",
        "description": "Exact ERPNext/Frappe DocType name. Must exist in the available DocType list. Never invent a DocType."
      },
      "fields": {
        "type": "array",
        "description": "Actual fieldnames, aggregate expressions (e.g. ['customer', 'customer_name', 'sum(grand_total) as grand_total'] or ['item_code', 'sum(qty) as total_qty']), or date extraction expressions (e.g. ['MONTHNAME(posting_date) as month', 'MONTH(posting_date) as month_num', 'sum(grand_total) as grand_total'] or ['YEAR(posting_date) as year', 'sum(grand_total) as grand_total']). Use only fields that exist. For count and sum, include the minimum fields necessary to perform or describe the operation.",
        "items": {
          "type": "string"
        },
        "minItems": 1
      },
      "filters": {
        "type": "object",
        "description": "JSON object containing ERPNext/Frappe filters. Use {} only when no filters are required. If filtering by date (e.g. 'today', 'yesterday', 'this week', 'last 7 days', 'this month', or date range) and no specific field was named, ALWAYS filter by 'creation' (e.g. {'creation': ['between', ['YYYY-MM-DD 00:00:00', 'YYYY-MM-DD 23:59:59']]}). NEVER pass {} when a date filter is requested. NEVER guess date fields like 'posting_date' or 'reference_date' unless explicitly named by the user.",
        "additionalProperties": true
      },
      "group_by": {
        "type": "string",
        "description": "Optional field, date function, or comma-separated fields to group records by (e.g. 'customer', 'item_code', 'status', 'MONTH(posting_date)', 'YEAR(posting_date)'). When user asks for top entities by sum, amount, or highest sales (e.g. 'top 10 customer with highest sales', 'top 5 items by sales'), ALWAYS specify group_by (e.g. 'customer'), include aggregate expressions in fields (e.g. ['customer', 'customer_name', 'sum(grand_total) as grand_total']), order_by that aggregate in descending order (e.g. 'grand_total desc'), and set limit to the exact count requested. When user asks for month-wise, monthly, or period-wise summary (e.g. 'current year month wise sales', 'monthly sales'), ALWAYS specify group_by with the date function (e.g. 'MONTH(posting_date)'), include month name/number and aggregate sum in fields (e.g. ['MONTHNAME(posting_date) as month', 'MONTH(posting_date) as month_num', 'sum(grand_total) as grand_total']), and order_by 'month_num asc' or 'MONTH(posting_date) asc'. NEVER make 12 individual queries for each month, and NEVER query all individual records without group_by to aggregate locally."
      },
      "order_by": {
        "type": "string",
        "description": "Optional sorting expression, for example 'creation desc', 'grand_total desc', 'posting_date asc', 'month_num asc', or 'MONTH(posting_date) asc'. Primarily used with list operations. When sorting by date or returning date-wise records, default to 'creation desc' unless another order is requested. Use 'desc' for top/highest/descending and 'asc' for bottom/lowest/ascending. Do not include trailing commas or words other than 'asc' or 'desc'."
      },
      "limit": {
        "type": "integer",
        "description": "Maximum number of records returned for a list operation. For 'top N' or 'first N' queries (e.g. 'top 10 customer', 'top 5 items'), STRICTLY set limit to that exact number N (e.g. 10, 5). NEVER set limit to 1000 or invent numbers. Do not use for count or sum operations.",
        "minimum": 1
      },
      "offset": {
        "type": "integer",
        "description": "Number of matching records to skip for pagination. Use only for list operations. Start at 0.",
        "minimum": 0
      },
      "sum_field": {
        "type": "string",
        "description": "Actual numeric ERPNext field to sum when operation is sum. Must exist in the selected DocType."
      }
    },
    "required": [
      "operation",
      "doctype",
      "fields",
      "filters"
    ],
    "additionalProperties": false
  }
}
